if __name__ == '__main__':
    path, wage_csv = sys.argv[1], sys.argv[2]
    d = json.load(open(path, encoding='utf-8'))
    w = {int(r['jy']): r for r in csv.DictReader(open(wage_csv, encoding='utf-8-sig'))}
    d['min_wage_1405'] = float(w[1405]['base_toman'])
    d['min_wage_1405_total'] = float(w[1405]['total_toman'])
    d['sources'] = SOURCES
    d['assumptions'] = ASSUME
    json.dump(d, open(path, 'w', encoding='utf-8'), ensure_ascii=False, separators=(',', ':'))
    print('ok', len(SOURCES), len(ASSUME), d['min_wage_1405'])
